 protected void onCreate(Bundle b){super.onCreate(b);if(getIntent().getBooleanExtra("modern",false)){getIntent().removeExtra("modern");try{ThemeCheckpoint.save(this);ThemePacks.apply(this,3);}catch(Exception e){notice(L.t("Tema nu a putut fi aplicată"));}}if(getIntent().getBooleanExtra("material",false)){android.content.SharedPreferences a=getSharedPreferences("appearance",0);getSharedPreferences("style-history",0).edit().putInt("theme",a.getInt("theme",0)).putInt("accent",a.getInt("accent",-1)).commit();a.edit().putInt("theme",9).remove("accent").commit();palette=Appearance.palette(this);}home();}
