 private void apps(){list(L.t("Teme pe aplicații"),Arrays.asList(LABELS),0,new Choice(){public void pick(final int app){ArrayList<String> themes=new ArrayList<String>();themes.add(L.t("Implicit · ")+(app<2&&!getSharedPreferences("appearance",0).getBoolean("unified-phone",false)?"Leo Night":L.t("tema generală")));themes.addAll(Arrays.asList(Appearance.THEMES));list(LABELS[app],themes,0,new Choice(){public void pick(int i){sample(APPS[app],i-1,-2);}},"",null);back=new Runnable(){public void run(){apps();}};}},"",null);back=new Runnable(){public void run(){home();}};}
 private void sample(final String app,final int theme,final int accent){begin(L.t("Previzualizare stil"));int t=theme<0?getSharedPreferences("appearance",0).getInt("theme",0):theme;int[] colors=Appearance.COLORS[Math.max(0,Math.min(Appearance.COLORS.length-1,t))].clone();int chosenAccent=accent== -2?getSharedPreferences("appearance",0).getInt("accent",-1):accent;if(chosenAccent>=0&&chosenAccent<Appearance.ACCENTS.length)colors[2]=Appearance.ACCENTS[chosenAccent];final Appearance.Palette sample=app!=null&&theme<0&&!getSharedPreferences("appearance",0).getBoolean("unified-phone",false)&&(app.equals("PhoneActivity")||app.equals("InCallActivity"))?PhoneTheme.palette():new Appearance.Palette(colors);root.addView(new View(this){final Paint p=new Paint(3);protected void onDraw(Canvas c){c.drawColor(sample.background);p.setColor(sample.card);c.drawRect(8,16,getWidth()-8,80,p);p.setColor(Color.WHITE);p.setTextSize(21);c.drawText(L.t("Leo · aplicație"),18,54,p);p.setColor(sample.selection);c.drawRect(8,100,getWidth()-8,150,p);p.setColor(sample.ink);c.drawText(L.t("Selecție"),18,132,p);p.setColor(sample.accent);c.drawRect(8,170,getWidth()-8,175,p);}},new LinearLayout.LayoutParams(-1,0,1));left=new Runnable(){public void run(){SharedPreferences.Editor e=getSharedPreferences("appearance",0).edit();if(app==null)e.putInt("accent",accent);else if(theme<0)e.remove("app-theme-"+app);else e.putInt("app-theme-"+app,theme);e.apply();notice(L.t("Stil salvat · se aplică la redeschidere"));home();}};back=new Runnable(){public void run(){home();}};footer(L.t("Aplică"),L.t("Mostră"),L.t("Anulează"));}
